<?php
require dirname(__DIR__).'/includes/bootstrap.php'; require_login(); $bid=current_branch_id(); ensure_continuation_schema(); $qterm=trim($_GET['q']??''); $results=[]; if($qterm!==''){ $like='%'.$qterm.'%';
 if(can('customers.view')) foreach(all('SELECT id,full_name title,phone sub FROM customers WHERE branch_id=? AND (full_name LIKE ? OR phone LIKE ? OR customer_no LIKE ?) LIMIT 10',[$bid,$like,$like,$like]) as $r)$results[]=['Customer',$r['title'],$r['sub'],'customer_view.php?id='.$r['id']];
 if(can('sales.view')) foreach(all('SELECT id,invoice_no title,status sub FROM sales WHERE branch_id=? AND invoice_no LIKE ? LIMIT 10',[$bid,$like]) as $r)$results[]=['Invoice',$r['title'],$r['sub'],'sale_view.php?id='.$r['id']];
 if(can('inventory.view')) foreach(all('SELECT id,name title,barcode sub FROM products WHERE branch_id=? AND (name LIKE ? OR barcode LIKE ? OR brand LIKE ?) LIMIT 10',[$bid,$like,$like,$like]) as $r)$results[]=['Product',$r['title'],$r['sub'],'inventory.php?q='.urlencode($qterm)];
 if(can('staff.view')) foreach(all('SELECT id,full_name title,role_title sub FROM staff WHERE branch_id=? AND (full_name LIKE ? OR phone LIKE ? OR employee_no LIKE ?) LIMIT 10',[$bid,$like,$like,$like]) as $r)$results[]=['Staff',$r['title'],$r['sub'],'staff.php?q='.urlencode($qterm)];
 if(can('appointments.view')) foreach(all('SELECT id,appointment_no title,status sub FROM appointments WHERE branch_id=? AND appointment_no LIKE ? LIMIT 10',[$bid,$like]) as $r)$results[]=['Appointment',$r['title'],$r['sub'],'appointments.php?edit='.$r['id']];
 if(can('appointments.view')) foreach(all('SELECT f.id,CONCAT(c.full_name," - ",s.name) title,CONCAT("Due ",f.due_date," • ",f.status) sub FROM customer_service_continuations f JOIN customers c ON c.id=f.customer_id JOIN services s ON s.id=f.service_id WHERE f.branch_id=? AND (c.full_name LIKE ? OR c.phone LIKE ? OR s.name LIKE ?) LIMIT 10',[$bid,$like,$like,$like]) as $r)$results[]=['Continuation',$r['title'],$r['sub'],'continuations.php?status=all']; }
$title='Search Everywhere'; $subtitle='Find customers, staff, products, appointments, invoices, suppliers and equipment.'; include dirname(__DIR__).'/includes/header.php';?><section class="card"><form class="toolbar"><input name="q" value="<?=e($qterm)?>" placeholder="Search customer, invoice, product…" style="min-width:320px"><button class="btn">Search</button></form><?php if($qterm===''):?><p class="muted">Type a search term above.</p><?php else:?><div class="table-wrap"><table><thead><tr><th>Type</th><th>Name / Number</th><th>Details</th><th>Open</th></tr></thead><tbody><?php foreach($results as $r):?><tr><td><?=e($r[0])?></td><td><?=e($r[1])?></td><td><?=e($r[2])?></td><td><a class="btn small light" href="<?=e($r[3])?>">Open</a></td></tr><?php endforeach;if(!$results):?><tr><td colspan="4" class="text-center muted">No results found.</td></tr><?php endif;?></tbody></table></div><?php endif;?></section><?php include dirname(__DIR__).'/includes/footer.php'; ?>